START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261016191117_AddCompetitionOperations') THEN
    CREATE TABLE "EquipmentAcknowledgement" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "CompetitionId" integer NOT NULL,
        "ItemKey" character varying(300) NOT NULL,
        "AcknowledgedAt" timestamp with time zone NOT NULL,
        "AcknowledgedByUserId" text,
        CONSTRAINT "PK_EquipmentAcknowledgement" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_EquipmentAcknowledgement_Competitions_CompetitionId" FOREIGN KEY ("CompetitionId") REFERENCES "Competitions" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261016191117_AddCompetitionOperations') THEN
    CREATE TABLE "RaceScoreEvent" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "RaceId" integer NOT NULL,
        "Revision" integer NOT NULL,
        "Kind" integer NOT NULL,
        "BeforeJson" text NOT NULL,
        "AfterJson" text NOT NULL,
        "ActorUserId" text,
        "Reason" character varying(1000) NOT NULL,
        "RequestId" character varying(100) NOT NULL,
        "PayloadFingerprint" character varying(64) NOT NULL,
        "CreatedAt" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_RaceScoreEvent" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_RaceScoreEvent_Races_RaceId" FOREIGN KEY ("RaceId") REFERENCES "Races" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261016191117_AddCompetitionOperations') THEN
    CREATE TABLE "RaceScoreState" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "RaceId" integer NOT NULL,
        "Revision" integer NOT NULL,
        "IsSignedOff" boolean NOT NULL,
        "SignedOffAt" timestamp with time zone,
        "SignedOffByUserId" text,
        "UpdatedAt" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_RaceScoreState" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_RaceScoreState_Races_RaceId" FOREIGN KEY ("RaceId") REFERENCES "Races" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
