    CREATE TABLE "Rulebook" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "CompetitionId" integer NOT NULL,
        "Title" character varying(200) NOT NULL,
        "Edition" character varying(100) NOT NULL,
        "SourceUrl" character varying(2000),
        "Text" text NOT NULL,
        "UpdatedAt" timestamp with time zone NOT NULL,
        "UpdatedByUserId" text,
        CONSTRAINT "PK_Rulebook" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Rulebook_Competitions_CompetitionId" FOREIGN KEY ("CompetitionId") REFERENCES "Competitions" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

